from pathlib import Path
import json,hashlib,collections,html
from PIL import Image,ImageDraw,ImageFont
R=Path(__file__).resolve().parent;P=R.parent
def load(n):return json.loads((R/n).read_text(encoding='utf-8'))
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
e=lambda x:html.escape(str(x))
packet=load('FOCAL-READINGS.json');diag=load('CORPUS-G-DIAGNOSTIC.json');controls=load('CONTROL-PACKET.json')
observations=[
 dict(locus='f70v1.S2.6',hand='4',position='Single-word figure/star label, not a prose right margin',reading='H/K/V/U oalcheg',crop='aries-anchor-upright',context='aries-context',assessment='A looped head and descending terminal stroke are visible. No obvious missing ink, fold or detached punctuation explains away the ending. Retain g as the source reading. Similarity to looped m-labelled forms is not sufficient to identify the sign.',status='Distinct written shape present; g-versus-m allography unresolved.'),
 dict(locus='f39r.P.4',hand='2',position='Physical end of fourth prose line',reading='H okalcheg; C okal.cheg; F/U okalchem',crop='f39r-word',context='f39r-context',assessment='Looped terminal and downward extension visible at right of line. Nearby same-page m-labelled forms also have descending/looped components, but entry strokes and preceding signs differ. Static image does not establish whether a distinctive g sign, an m variant, or a connected sequence is intended. Word join/split remains disputed.',status='Clear g/m reading divergence at same ink; no adjudicated replacement.'),
 dict(locus='f45v.P.6',hand='1',position='Line ending after a plant-interrupted text span',reading='H/C cheg; F/G chem',crop='f45v-word',context='f45v-context',assessment='A looped final form with a long sloping continuation is visible. Plant layout sets the text boundary; this is not an unlimited ordinary right margin. Same-page chom/pchom control contexts retained.',status='Compatible with a closing-form convention; not proof of m identity.'),
 dict(locus='f103r.P.35',hand='3',position='Physical prose line end',reading='H lcheg; F lchem',crop='f103r-word',context='f103r-context',assessment='Rounded upper loop and extended sloping descender are clear. The adjacent lines show other long terminal strokes. The m-labelled otam control is preserved in a wider crop. Relative loop/entry geometry varies, and no invariant diagnostic was established from this reader sample.',status='Clear ink, transcription class differs; allograph question remains.'),
 dict(locus='f83r.P.5',hand='2',position='Interior word, followed by shedy and additional words',reading='H/C/V cheg; F chem',crop='f83r-line5',context='f83r-context',assessment='A more compact looped ending is visible in continuous text. It is not a physical line-ending flourish. This is a direct counterexample to any rule claiming every H g is merely a final-line extension.',status='Interior counterexample to a strict line-end-only account.'),
 dict(locus='f67v1.Y.3',hand='4',position='Penultimate word of radial line, followed by oty',reading='H/U/V ypcheg',crop='f67v-radials',context='f67v-radials',assessment='An ending with a loop and downward continuation occurs before a following word. This provides a same-hand4 non-line-final comparison to the Aries anchor, though radial and label layout differ.',status='Agreed hand4 form outside a single-word label; no name meaning inferred.'),
 dict(locus='f66r.W.1',hand=next(x[3] for x in packet['f66r.W.1'] if x[0]=='H'),position='Final word/sign of a detached figure caption',reading='H ykchscheg; V/U ykees cheg; C ynchscheim, with earlier segmentation alternatives',crop='f66r-caption',context='f66r-caption',assessment='Last form is heavily inked with a loop/head and descending finish. Earlier word division and sign decomposition also differ, so this is not a clean one-sign minimal pair.',status='Compound segmentation uncertainty, preserved rather than harmonised.'),
 dict(locus='f69r.R.2',hand='4',position='First word of a short radial line',reading='H cheg; U/V chey, with subsequent words also differing',crop='f69r-radials',context='f69r-radials',assessment='Faint radial writing inspected in context. The first-word terminal is not secure enough here to decide g versus y independently. It is not a terminal word of the full radial line.',status='Unresolved image/reading alternative; not a confirmed g exemplar.'),
]
save('IMAGE-OBSERVATIONS.json',observations)
crop_notes=dict(excluded_locator_trials={'aries-label-rotated':'This preliminary lower-band crop is a neighbouring inscription, not the anchor. Retained for audit; excluded from comparison sheet. Correct anchor is aries-other-label/aries-anchor-upright.','f83r-word':'Initial tight crop insufficient for secure whole-word localisation. Final comparison uses full P5 line and its cheg segment.'},operations='Rectangular crops only, with the anchor additionally rotated125degrees using bicubic interpolation. Original full scans and unrotated contexts retained. Contact sheets scale to fit; they are not glyph-size measurements. No generative restoration, sharpening, thresholding or stroke reconstruction.')
save('CROP-QA.json',crop_notes)
sources=[dict(url='https://collections.library.yale.edu/manifests/2002046',used='Public Yale full-scan image IDs, dimensions and originals; downloaded for this image audit'),dict(url='https://www.ic.unicamp.br/en/~stolfi/EXPORT/voynich/encodings/encodings.html',used='Historical transliteration table distinguishes EVA m and g (FSG K and6 in that table). Alphabet availability does not settle how each original transcriber classified a particular mark.'),dict(url='https://www.voynich.nu/transcr.html',used='Historical F/Currier and EVA transliteration provenance and differing symbol inventories'),dict(url='https://voynichtranscription.co.uk/mappings.php',used='Current character table also retains separate EVA m/g graphic classes; this is a convention, not demonstrated phonetic distinction.')]
save('SOURCES.json',sources)
fcounts=collections.Counter(x['F_status'] for x in diag);same=[x for x in diag if x['F_status']=='same prefix'];endings=collections.Counter(x['F_word'][-1] for x in same)
baseline=load('POSITION-BASELINE.json')['counts']
summary=dict(judgment='Graphic variation and transliteration classification plausibly contribute to g rarity. Position is associated with g/m endings in paragraph-format H text, but g is not confined to physical line ends. Images do not establish a universal g=m rule or distinct phonetic value.',focal_loci=len(observations),H_word_final_g_tokens_all_formats=len(diag),F_comparison_status=dict(fcounts),F_identical_prefix_cases=len(same),F_last_sign_among_identical_prefix=dict(endings),paragraph_positions=baseline,anchor='Preserve oalcheg H/K/V/U. Do not replace it by oalchem.',rescoring='No g/m collapse or rarity rescore performed. Prior literal-g scores are conditional on that graphic classification, not independent evidence of phonetic naming.',unresolved=['Distinct grapheme versus allograph/connected sequence','Within-hand stable shape boundaries','Whether closing forms encode content, a grammatical convention or purely graphical variation','Phonetic relevance'])
save('RESULTS.json',summary)

# Independent source-count verification and image provenance checks.
rows=json.loads((P/'complete-atlas-v56/ROWS.json').read_text());n=sum(bool(w and w.endswith('g')) for x in rows if x[0]=='H' for w in x[9]);assert n==len(diag)==79
for p,h in load('PRE-IMAGE-FREEZE.json').items():assert sha(Path(p))==h
for x in load('IMAGE-RECEIPTS.json'):
 p=Path(x['file']);assert sha(p)==x['sha256'];im=Image.open(p);assert list(im.size)==[x['width'],x['height']]
assert len(same)==38 and endings=={'m':36,'d':1,'y':1}
save('VERIFICATION.json',dict(original_input_freeze_unchanged=True,all8_downloaded_images_hash_and_dimensions_verified=True,original_readings_preserved=True,corpus_g_count_recomputed=n,matched_F_prefix_examples_rechecked=38,crop_localisation_trials_retained=True,comparative_sheet_visually_inspected=True,expert_palaeographic_adjudication=False,normalisation_applied=False,historical_names_or_sounds_fitted=False,report_appearance='HTML appearance unreviewed; standalone comparison image inspected.'))

# Compact image output. Original crops remain available for pixel inspection.
font=ImageFont.truetype(r'C:\Windows\Fonts\arial.ttf',17)
items=[('Aries: oalcheg (H/K/V/U)','aries-anchor-word.png',None),('f39r: okalcheg / okalchem','f39r-word.png',None),('f45v: cheg / chem','f45v-word.png',None),('f103r: lcheg / lchem','f103r-word.png',None),('f83r: interior cheg / chem','f83r-line5.png',(870,0,1250,140))]
sheet=Image.new('RGB',(1200,600),'#ffffff');draw=ImageDraw.Draw(sheet)
for i,(label,name,box) in enumerate(items):
 x=(i%3)*400;y=(i//3)*300;draw.text((x+12,y+12),label,font=font,fill='black');im=Image.open(R/'crops'/name).convert('RGB')
 if box:im=im.crop(box)
 if i==0:im=im.resize((350,230),Image.Resampling.NEAREST)
 im.thumbnail((375,240));sheet.paste(im,(x+12,y+45));draw.rectangle((x,y,x+399,y+299),outline='#b8b8b8')
draw.text((820,340),'Scaled crops; not size measurements.',font=font,fill='black');draw.text((820,370),'Originals and context in report.',font=font,fill='black');sheet.save(R/'comparison-compact.png')
body='<h1>g / m endings · manuscript image audit</h1><p class="lede">A graphic or transcriptional explanation is plausible. A universal g=m replacement, or an exclusively line-end flourish, is not established.</p><p>Eight exposed candidate locations inspected in Yale full scans and native-resolution context crops. Alternate readings remain source records. This is a reader audit, not expert palaeographic adjudication or a sound/name test.</p><img src="comparison-compact.png" alt="Five manuscript ending comparisons"><p>Contact-sheet images are scaled to fit. Open each unaltered crop and context below for detail. The Aries label is rotated for reading; its original context is retained.</p>'
body+='<h2>What this changes</h2><p>The anchor has a clear looped/descending final mark; it is not an obvious damaged or missing sign. Several marks rendered g in H are m in F. These observations make the earlier rarity score conditional on a disputed graphic classification. Similar-looking forms across different hands do not establish one grapheme, and agreement on the Aries spelling is retained.</p><p>EVA tables distinguish m and g as separate graphic classes; they do not establish different sounds. The historical F transcription was produced using an earlier alphabet and later converted. The 36/38 comparison can reflect classification/encoding choices as well as reader judgment, and is not38 independent expert adjudications.</p>'
body+='<h2>Eight image comparisons</h2>'
for o in observations:
 body+=f'<article><h3>{e(o["locus"])} · local hand {e(o["hand"])}</h3><p><b>{e(o["reading"])}</b><br>{e(o["position"])}</p><img loading="lazy" src="crops/{e(o["crop"])}.png" alt="Native crop"><p>{e(o["assessment"])}</p><p><b>{e(o["status"])}</b></p><details><summary>Wider context and every reading</summary><img loading="lazy" src="crops/{e(o["context"])}.png" alt="Wider image context"><pre>'+e(json.dumps(packet[o['locus']],indent=2))+'</pre></details></article>'
body+='<h2>Same-page m-ending controls</h2><p>Nearest preceding/following complete H m-ending tokens were selected in source order before image interpretation. They are graphic comparison candidates, not known phonetic m. Not every cropped context isolates an individual sign; full sources and token positions remain available.</p>'
for n,label in [('aries-m-control','Aries S2.1 · am within a multiword label'),('f39r-control-wide','f39r · dam control context'),('f45v-m-control','f45v · chom context'),('f103r-control-wide','f103r · otam context')]:body+=f'<details><summary>{e(label)}</summary><img loading="lazy" src="crops/{n}.png" alt="Same-page control context"></details>'
body+='<p>m-labelled forms also have looped/descending components. Preceding signs, entry connections and local execution differ; this sample did not yield a stable within-hand diagnostic proving the anchor either identical to, or different from, all m-labelled forms.</p>'
body+='<h2>Position and transcription diagnostics</h2><p>Across all formats, H has79 word-final g tokens:54 final source tokens,14 interior,8 single-word units and3 first tokens. Circular/radial source endpoints are not ordinary page margins.</p><p>Among the79 cases, F is missing at20 loci;16 have differing slot counts and5 differing prefixes/unknowns. The remaining38 have matching slots and exactly the same word prefix: F ends36 with m, one with d and one with y. This strict subset avoids silently aligning changed word boundaries; all excluded cases are retained.</p><table><tr><th>H paragraph-format words</th><th>Final source slot / total</th><th>Descriptive fraction</th></tr>'
for kind in ['g','m','other']:
 c=baseline[kind];body+=f'<tr><td>Ending {e(kind)}</td><td>{c["source_line_final"]} / {c["tokens"]}</td><td>{100*c["source_line_final"]/c["tokens"]:.1f}%</td></tr>'
body+='</table><p>This follow-up is descriptive and was specified after seeing the initial position counts. g/m endings both favour the last source slot compared with other endings, but word family, hand, section and position are not jointly controlled. H f83r.P.5 and agreed hand4 ypcheg f67v1.Y.3 occur before following words; therefore an exclusively physical-line-end explanation is insufficient.</p>'
body+='<h2>Interpretation retained</h2><ul><li>A distinct graphic sign is possible; the anchor is not unreadable.</li><li>An allographic, connected-sign or closing-form convention is also possible, supported as a lead by image similarity and systematic g/m transliteration differences.</li><li>A positional convention may contribute, but is not an exceptionless line-end rule.</li><li>No phonetic value, semantic function or proper-name status follows from these observations.</li></ul><p>No global merge or new anomaly rescore was performed. A separate frozen g/m sensitivity could measure how much of the earlier rank depends on this distinction, while preserving the original readings.</p>'
body+='<h2>Receipts and limits</h2><p>Earlier locator-trial crops are retained, including a neighbouring Aries inscription initially cropped while locating the anchor. It is explicitly excluded from the comparison. Correct anchor: aries-other-label, aries-anchor-upright, aries-anchor-word. Native pixels were cropped/rotated only; no generated restoration or altered stroke shapes. Full original scans, source URLs, hashes and dimensions are saved locally.</p>'
for fn in ['PROTOCOL.json','IMAGE-SOURCES.json','IMAGE-RECEIPTS.json','CROPS.json','CROP-QA.json','IMAGE-OBSERVATIONS.json','FOCAL-READINGS.json','CONTROL-PACKET.json','CORPUS-G-DIAGNOSTIC.json','POSITION-BASELINE.json','RESULTS.json','VERIFICATION.json']:
 body+=f'<p><a href="{fn}">{fn}</a></p>'
for s in sources:body+=f'<p><a href="{e(s["url"])}">{e(s["used"])}</a></p>'
body+='<p>Image credit: Cipher manuscript, Beinecke MS408, Yale University Library. Report appearance unreviewed; standalone comparison sheet inspected.</p>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>g/m ending image audit · v89</title><style>body{font:17px system-ui;max-width:1150px;margin:36px auto;padding:0 22px;background:#f5f2e9;color:#193c39;line-height:1.5}.lede{font-size:22px}h1{line-height:1.2}img{max-width:100%;height:auto;display:block;margin:18px auto}article{padding:12px 0;border-bottom:2px solid #abc}table{border-collapse:collapse;width:100%}td,th{border:1px solid #abc;padding:8px;text-align:left}details{border-bottom:1px solid #bbc;padding:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}a{color:#17616d}</style>'+body+'</html>',encoding='utf-8')
save('SHA256SUMS.json',{str(p.relative_to(R)):sha(p) for p in R.rglob('*') if p.is_file() and p.name!='SHA256SUMS.json'})
print(json.dumps(dict(F_same_prefix=len(same),F_m=endings['m'],H_g_prose_final=baseline['g'],source_images=8,observations=len(observations)),indent=2))
